def compare_commits(conn, delta):
    if not isinstance(delta,int) or isinstance(delta,bool):raise ValueError("integer delta required")
    with conn.cursor() as cur:
        cur.execute("SELECT @@tidb_enable_1pc,@@tidb_enable_async_commit,@@tidb_txn_mode");previous=cur.fetchone()
    try:
        with conn.cursor() as cur:
            cur.execute("SET SESSION tidb_enable_1pc=1");cur.execute("SET SESSION tidb_enable_async_commit=0");cur.execute("SET SESSION tidb_txn_mode='optimistic'")
        result={}
        for name,keys in [("single",(125,)),("multi",(125,875))]:
            conn.begin()
            with conn.cursor() as cur:
                for key in keys:cur.execute("UPDATE txn_ranges SET v=v+%s WHERE id=%s",(delta,key))
            conn.commit()
            with conn.cursor() as cur:
                cur.execute("SELECT @@tidb_last_txn_info");result[name]=json.loads(cur.fetchone()[0])
        return result
    except BaseException:
        conn.rollback();raise
    finally:
        with conn.cursor() as cur:
            cur.execute("SET SESSION tidb_enable_1pc=%s",(previous[0],));cur.execute("SET SESSION tidb_enable_async_commit=%s",(previous[1],));cur.execute("SET SESSION tidb_txn_mode=%s",(previous[2],))

