        cur.execute("SHOW TABLE load_gate REGIONS");native=cur.fetchall()
    regions=[pd_get("/pd/api/v1/region/id/"+str(r[0])) for r in native]
    stores=pd_get("/pd/api/v1/stores")["stores"]
    up={s["store"]["id"] for s in stores if s["store"].get("state_name")=="Up" and s["store"].get("last_heartbeat",0)>0}
    leaders={r.get("leader",{}).get("store_id") for r in regions};leaders.discard(None)
    counts=collections.Counter();mapping=[]
    for ident,value in rows:
        with conn.cursor() as cur:
            cur.execute("SELECT TIDB_ENCODE_RECORD_KEY('training','load_gate',%s)",(ident,));raw=bytes.fromhex(cur.fetchone()[0])
        matches=[r["id"] for r in regions if (not r.get("start_key") or decode_pd_key(r["start_key"])<=raw) and (not r.get("end_key") or raw<decode_pd_key(r["end_key"]))]
        if len(matches)!=1:raise ValueError("key not covered exactly once")
        counts[matches[0]]+=1;mapping.append((ident,matches[0]))
    healthy=len(regions)==4 and len(leaders)>=minimum_leaders and all(not r[6] for r in native)
    for region in regions:
        voters=[p for p in region["peers"] if p.get("role_name")=="Voter"]
        healthy=healthy and len(voters)==3 and len({p["store_id"] for p in voters})==3 and all(p["store_id"] in up for p in voters) and not region.get("pending_peers") and not region.get("down_peers")
    covered=set(counts)=={r["id"] for r in regions}
    ready=True
    if ready:
        try:
            conn.begin()
            with conn.cursor() as cur:
                for row in rows:cur.execute("INSERT INTO load_gate(id,v) VALUES(%s,%s)",tuple(row))
            conn.commit()
        except BaseException:conn.rollback();raise
    return {"admitted":ready,"regions":regions,"mapping":mapping,"writes_per_region":dict(counts),"leader_stores":sorted(leaders)}

