def compact_sql(sql):return re.sub(r'\s+','',sql).replace('`','').lower().rstrip(';')
class TraceCursor:
 def __init__(self,cursor,owner):self.cursor=cursor;self.owner=owner;self.statement='';self.params=None
 def __enter__(self):self.cursor.__enter__();return self
 def __exit__(self,*args):return self.cursor.__exit__(*args)
 def __getattr__(self,name):return getattr(self.cursor,name)
 def execute(self,statement,params=None):
  self.statement=statement;self.params=params
  return self.cursor.execute(statement,params)
 def fetchall(self):
  rows=self.cursor.fetchall();self.owner.observed.append((self.statement,self.params,rows));return rows
 def fetchone(self):
  row=self.cursor.fetchone();self.owner.observed.append((self.statement,self.params,(row,)));return row
class Trace:
 def __init__(self,conn):self.conn=conn;self.observed=[]
 def cursor(self,*args,**kwargs):return TraceCursor(self.conn.cursor(*args,**kwargs),self)
 def __getattr__(self,name):return getattr(self.conn,name)
